// Pure builders for write-contract-files.mjs: bundled contract in, TypeScript source text out.

const HEADER =
  "// Generated by scripts/write-contract-files.mjs from the contract. Do not edit.\n";
const REF = "#/components/schemas/";

const operationsOf = (contract) =>
  Object.entries(contract.paths).map(([url, item]) => ({ url, op: item.post }));

const refName = (ref) => {
  if (!ref.startsWith(REF)) {
    throw new Error(
      `Only component schema references are supported, found ${ref}`,
    );
  }
  return ref.slice(REF.length);
};

const jsonOf = (op) => op?.content?.["application/json"];

// The schema keywords the transport's normaliser and development-build validator read. Everything
// else (descriptions, formats for documentation) stays out of the bundle.
const KEEP = [
  "type",
  "nullable",
  "enum",
  "required",
  "minimum",
  "maximum",
  "minLength",
  "maxLength",
  "minItems",
  "maxItems",
  "pattern",
  "x-omv-int64",
  "x-omv-coerce",
];

function slim(schema, used) {
  if (!schema || typeof schema !== "object") {
    return schema;
  }
  if (schema.$ref) {
    const name = refName(schema.$ref);
    used.add(name);
    return { $ref: name };
  }
  const out = {};
  for (const key of KEEP) {
    if (key in schema) {
      out[key] = schema[key];
    }
  }
  if (schema.properties) {
    out.properties = Object.fromEntries(
      Object.entries(schema.properties).map(([k, v]) => [k, slim(v, used)]),
    );
  }
  if (schema.additionalProperties !== undefined) {
    out.additionalProperties =
      typeof schema.additionalProperties === "object"
        ? slim(schema.additionalProperties, used)
        : schema.additionalProperties;
  }
  if (schema.items) {
    out.items = slim(schema.items, used);
  }
  for (const key of ["oneOf", "anyOf", "allOf"]) {
    if (schema[key]) {
      out[key] = schema[key].map((s) => slim(s, used));
    }
  }
  if (schema.discriminator) {
    out.discriminator = {
      propertyName: schema.discriminator.propertyName,
      ...(schema.discriminator.mapping && {
        mapping: Object.fromEntries(
          Object.entries(schema.discriminator.mapping).map(([k, v]) => [
            k,
            refName(v),
          ]),
        ),
      }),
    };
  }
  return out;
}

/** The operation table and the slimmed schemas it refers to. */
export function buildOperationTable(contract) {
  const used = new Set();
  const rows = {};
  for (const { url, op } of operationsOf(contract)) {
    const response = jsonOf(op.responses["200"]);
    const task = op["x-omv-task"];
    if (task?.result) {
      used.add(task.result);
    }
    rows[url] = {
      operationId: op.operationId,
      service: op["x-omv-rpc"].service,
      method: op["x-omv-rpc"].method,
      role: op["x-omv-role"],
      readonly: op["x-omv-readonly"] === true,
      dirty: op["x-omv-dirty"] === true,
      ...(task && { task: { ...(task.result && { result: task.result }) } }),
      ...(op["x-omv-download"] && {
        download: { contentType: op["x-omv-download"].contentType },
      }),
      ...(op["x-omv-destructive"] && { destructive: op["x-omv-destructive"] }),
      ...(op["x-omv-omit"] && { omit: op["x-omv-omit"] }),
      response: response ? slim(response.schema, used) : null,
    };
  }
  // Close over references: a schema may refer to others.
  const schemas = {};
  const queue = [...used];
  while (queue.length) {
    const name = queue.shift();
    if (name in schemas) {
      continue;
    }
    const before = new Set(used);
    schemas[name] = slim(contract.components.schemas[name], used);
    for (const n of used) {
      if (!before.has(n)) {
        queue.push(n);
      }
    }
  }
  const sortedSchemas = Object.fromEntries(
    Object.keys(schemas)
      .sort()
      .map((k) => [k, schemas[k]]),
  );
  return `${HEADER}import type { OperationTable, SchemaTable } from "../types.ts";

export const OPERATIONS = ${JSON.stringify(rows, null, 2)} as const satisfies OperationTable;

export type OperationUrl = keyof typeof OPERATIONS;

export const SCHEMAS: SchemaTable = ${JSON.stringify(sortedSchemas, null, 2)};
`;
}

/** Every example of the contract, by operation id and name, with its HTTP status. */
export function buildExamples(contract) {
  const examples = contract.components?.examples ?? {};
  const resolve = (ex) =>
    ex.$ref ? examples[ex.$ref.replace("#/components/examples/", "")] : ex;
  const table = {};
  const defaults = {};
  for (const { op } of operationsOf(contract)) {
    const named = {};
    for (const [status, response] of Object.entries(op.responses)) {
      for (const [name, ex] of Object.entries(
        jsonOf(response)?.examples ?? {},
      )) {
        const value = resolve(ex).value;
        named[name] = {
          status: Number(status),
          value: value === undefined ? null : value,
        };
        if (status === "200" && !(op.operationId in defaults)) {
          defaults[op.operationId] = name;
        }
      }
    }
    // An operation that returns null has no 200 example; its mock answer is null, beside any
    // error examples it has.
    if (!jsonOf(op.responses["200"])) {
      named.null = { status: 200, value: null };
      defaults[op.operationId] = "null";
    }
    table[op.operationId] = named;
  }
  return `${HEADER}// Raw replies as rpc.php sends them, before the transport normalises them: a value may still
// carry a wire quirk such as [] for an empty map. They are the mock data (docs/04).
import type { ContractExampleTable } from "../../contract/types.ts";

export const CONTRACT_EXAMPLES = ${JSON.stringify(table, null, 2)} as const satisfies ContractExampleTable;

export const DEFAULT_EXAMPLE = ${JSON.stringify(defaults, null, 2)} as const satisfies Record<keyof typeof CONTRACT_EXAMPLES, string>;
`;
}

// ---- valibot form schemas ----

const pascal = (s) => s[0].toUpperCase() + s.slice(1);

function valibotOf(schema, contract, seen = []) {
  if (schema.$ref) {
    const name = refName(schema.$ref);
    if (seen.includes(name)) {
      throw new Error(`Recursive request schema ${name} is not supported`);
    }
    return valibotOf(contract.components.schemas[name], contract, [
      ...seen,
      name,
    ]);
  }
  let expr;
  if (schema.oneOf || schema.anyOf) {
    expr = `v.union([${(schema.oneOf ?? schema.anyOf).map((s) => valibotOf(s, contract, seen)).join(", ")}])`;
  } else if (schema.enum) {
    expr = `v.picklist(${JSON.stringify(schema.enum)})`;
  } else {
    switch (schema.type) {
      case "string": {
        const pipe = [];
        if (schema.minLength !== undefined) {
          pipe.push(`v.minLength(${schema.minLength})`);
        }
        if (schema.maxLength !== undefined) {
          pipe.push(`v.maxLength(${schema.maxLength})`);
        }
        if (schema.pattern) {
          pipe.push(
            `v.regex(new RegExp(${JSON.stringify(schema.pattern)}, "u"))`,
          );
        }
        expr = pipe.length
          ? `v.pipe(v.string(), ${pipe.join(", ")})`
          : "v.string()";
        break;
      }
      case "integer":
      case "number": {
        const pipe = schema.type === "integer" ? ["v.integer()"] : [];
        if (schema.minimum !== undefined) {
          pipe.push(`v.minValue(${schema.minimum})`);
        }
        if (schema.maximum !== undefined) {
          pipe.push(`v.maxValue(${schema.maximum})`);
        }
        expr = pipe.length
          ? `v.pipe(v.number(), ${pipe.join(", ")})`
          : "v.number()";
        break;
      }
      case "boolean":
        expr = "v.boolean()";
        break;
      case "array":
        expr = `v.array(${valibotOf(schema.items, contract, seen)})`;
        break;
      case "object": {
        const required = new Set(schema.required ?? []);
        const fields = Object.entries(schema.properties ?? {}).map(([k, s]) => {
          const inner = valibotOf(s, contract, seen);
          return `${JSON.stringify(k)}: ${required.has(k) ? inner : `v.optional(${inner})`}`;
        });
        // Strict: the form sends exactly the fields the contract names, never more.
        expr = `v.strictObject({ ${fields.join(", ")} })`;
        break;
      }
      default:
        throw new Error(
          `Request schema type ${schema.type} is not supported in forms`,
        );
    }
  }
  return schema.nullable ? `v.nullable(${expr})` : expr;
}

/**
 * One file per mutation with a request body that a person fills in (not tasks, and not Exec, which
 * is the task helper's), plus an
 * index. Each exports `<OperationId>RequestSchema` and its output type.
 */
export function buildForms(contract) {
  const files = {};
  const names = [];
  for (const { op } of operationsOf(contract)) {
    const body = jsonOf(op.requestBody);
    if (
      !body ||
      op["x-omv-readonly"] === true ||
      op["x-omv-task"] ||
      op["x-omv-rpc"].service === "Exec"
    ) {
      continue;
    }
    const name = `${pascal(op.operationId)}RequestSchema`;
    names.push([op.operationId, name]);
    files[`${op.operationId}.ts`] = `${HEADER}import * as v from "valibot";

/** The request body of ${op["x-omv-rpc"].service}.${op["x-omv-rpc"].method}, as the contract accepts it. */
export const ${name} = ${valibotOf(body.schema, contract)};

export type ${pascal(op.operationId)}FormValues = v.InferOutput<typeof ${name}>;
`;
  }
  files["index.ts"] =
    `${HEADER}${names.map(([id, name]) => `export { ${name}, type ${pascal(id)}FormValues } from "./${id}.ts";`).join("\n")}\n`;
  return files;
}
